<script setup lang="ts">
import { ref,computed,onMounted,watch,onUnmounted } from 'vue'
import { useApp } from '../stores/app'
import type { NewsSource } from '../lib/types'
import { categories } from '../lib/types'
import { supabase } from '../lib/supabase'
import { secureUrl,dateLabel,nextPublication } from '../lib/format'
import Icon from '../components/Icon.vue'
const app=useApp(),tab=ref('新闻管理'),query=ref(''),filter=ref('全部'),busy=ref(false),selected=ref(''),confirmation=ref(''),newToken=ref(''),clientName=ref(''),purpose=ref('ingest'),clients=ref<Record<string,any>[]>([]),raws=ref<Record<string,any>[]>([]),runs=ref<Record<string,any>[]>([])
const sourceForm=ref({name:'',url:'',category:'科技',license_note:'',official:false,focus:'general',source_type:'rss',api_adapter:null as null|'newsapi'|'github'|'huggingface',image_policy:'illustration',image_license:'',image_hosts:'' ,content_hosts:''})
const rows=computed(()=>app.posts.filter(p=>(filter.value==='全部'||p.status===filter.value)&&`${p.title} ${p.source_name}`.includes(query.value)))
watch(tab,()=>newToken.value='');onUnmounted(()=>newToken.value='')
const tabs=[['新闻管理','Layers3'],['Agent 控制台','Activity'],['信息源','Rss'],['GPT 接口','KeyRound']]
async function attempt(fn:()=>Promise<void>){busy.value=true;try{await fn()}catch(e){app.notify(app.errorMessage(e))}finally{busy.value=false}}
async function refresh(){await attempt(async()=>{await app.loadAdmin();if(!app.demo&&supabase){const results=await Promise.all([supabase.from('api_clients').select('id,name,scopes,active,created_at,expires_at'),supabase.from('raw_news').select('id,title,url,source_name,source_published_at,created_at').order('created_at',{ascending:false}).limit(40),supabase.from('agent_runs').select('*').order('created_at',{ascending:false}).limit(20)]);for(const r of results)if(r.error)throw r.error;clients.value=results[0].data||[];raws.value=results[1].data||[];runs.value=results[2].data||[]}})}
onMounted(refresh)
async function action(name:string,payload:Record<string,unknown>={}){await attempt(async()=>{const r=await app.admin(name,payload);if(r){app.notify(r.message||'操作成功');await app.load();await app.loadAdmin()}})}
async function change(id:string,status:'draft'|'published'){await attempt(async()=>{const p=app.posts.find(p=>p.id===id)!;if(app.demo&&p.origin==='demo'){app.notify('示例卡片为内置演示，编辑和发布请新建私人手记');return}if(status==='published'&&p.origin==='agent'){await app.admin('review-post',{post_id:id,decision:'approve'});await app.load()}else await app.savePost({...p,status,published_at:status==='published'?new Date().toISOString():null})})}
async function deleteSelected(){await attempt(async()=>{await app.deletePost(selected.value);selected.value='';confirmation.value=''})}
async function addSource(){if(!secureUrl(sourceForm.value.url)){app.notify('信息源需要 HTTPS 地址');return}await attempt(async()=>{const r=await app.admin('add-source',{...sourceForm.value,api_adapter:sourceForm.value.source_type==='api'?(sourceForm.value.api_adapter||'newsapi'):null,image_hosts:sourceForm.value.image_hosts.split(',').map(x=>x.trim()).filter(Boolean),content_hosts:sourceForm.value.content_hosts.split(',').map(x=>x.trim()).filter(Boolean)});if(r){app.notify('来源已添加');sourceForm.value={name:'',url:'',category:'科技',license_note:'',official:false,focus:'general',source_type:'rss',api_adapter:null,image_policy:'illustration',image_license:'',image_hosts:'',content_hosts:''};await app.loadAdmin()}})}
async function toggleSource(s:NewsSource){await action('toggle-source',{id:s.id,enabled:!s.enabled})}
async function createToken(){await attempt(async()=>{const result=await app.admin('create-client',{name:clientName.value,purpose:purpose.value});if(result){newToken.value=result.token;clientName.value='';await refresh()}})}
async function copyToken(){try{await navigator.clipboard.writeText(newToken.value);app.notify('已复制，请存入密码管理器或 GitHub Secrets')}catch{app.notify('请手动复制此一次性凭证')}}
</script>
<template><div class="page admin-page"><div class="page-heading"><div><div class="eyebrow">TECH SWIPE / CONTROL ROOM</div><h1>让好内容，有序发生<span class="orange">。</span></h1><p>新闻、Agent 与每日发布，都在你的掌控中。</p></div><button class="btn outline small" :disabled="busy" @click="refresh"><Icon name="RefreshCw" :size="15"/>刷新</button></div><div class="admin-stats"><div><Icon name="Layers3"/><span>已发布<strong>{{app.posts.filter(p=>p.status==='published').length}}</strong></span><small>内容资产</small></div><div><Icon name="FileText"/><span>待处理<strong>{{app.posts.filter(p=>p.status!=='published').length}}</strong></span><small>草稿与队列</small></div><div><Icon name="Activity"/><span>Agent 状态<strong class="stat-word">{{app.settings.agent_enabled?'已开启':'已暂停'}}</strong></span><span class="status-dot" :class="{paused:!app.settings.agent_enabled}"></span></div><div><Icon name="Clock3"/><span>计划发布<strong class="stat-word">08:00</strong></span><small>{{app.settings.timezone}}</small></div></div><div class="admin-tabs"><button v-for="[label,icon] in tabs" :key="label" :class="{active:tab===label}" @click="tab=label"><Icon :name="icon!" :size="16"/>{{label}}</button></div><template v-if="tab==='新闻管理'"><div class="admin-filter"><div class="search-field"><Icon name="Search" :size="17"/><input v-model="query" placeholder="搜索标题或来源" aria-label="后台搜索"/></div><select v-model="filter" aria-label="发布状态"><option value="全部">全部状态</option><option value="published">已发布</option><option value="draft">草稿</option><option value="queued">待发布</option></select><RouterLink to="/publish" class="btn primary small"><Icon name="Plus" :size="16"/>新建内容</RouterLink></div><div class="table-scroll"><table><thead><tr><th>内容 / 来源</th><th>分类</th><th>状态</th><th>核验</th><th>操作</th></tr></thead><tbody><tr v-for="p in rows" :key="p.id"><td><RouterLink :to="p.status==='published'?`/post/${p.id}`:`/edit/${p.id}`"><strong>{{p.title}}</strong><small>{{p.source_name}}</small></RouterLink></td><td>{{p.category}}</td><td><span :class="['status-badge',p.status]">{{{draft:'草稿',queued:'待发布',published:'已发布'}[p.status]}}</span></td><td>{{p.origin==='demo'?'演示':p.origin==='manual'?'私人手记':p.verification_status==='verified'?'已核验':'待审核'}}</td><td><div class="table-actions"><RouterLink :to="`/edit/${p.id}`" class="icon-btn" aria-label="编辑新闻"><Icon name="Pencil" :size="15"/></RouterLink><button class="icon-btn" :disabled="busy" :aria-label="p.status==='published'?'取消发布':'审核并发布'" @click="change(p.id,p.status==='published'?'draft':'published')"><Icon :name="p.status==='published'?'Pause':'Play'" :size="15"/></button><button class="icon-btn" :class="{orange:p.pinned}" :disabled="busy" aria-label="置顶" @click="attempt(()=>app.savePost({...p,pinned:!p.pinned}))"><Icon name="Pin" :size="15"/></button><button class="icon-btn danger-hover" aria-label="删除新闻" @click="selected=p.id;confirmation=p.title"><Icon name="Trash2" :size="15"/></button></div></td></tr></tbody></table><div v-if="!rows.length" class="table-empty">这里还没有内容，先添加一条私人手记或接入信息源。</div></div></template><template v-else-if="tab==='Agent 控制台'"><div class="control-grid"><section class="form-card"><h3><Icon name="Activity" :size="18"/>采集与制稿</h3><p>先收集候选，再核验和生成。真实性优先，不足目标数量时不补造内容。</p><div class="control-actions"><button class="btn primary small" :disabled="busy" @click="action('enqueue-agent',{kind:'prepare'})"><Icon name="Play" :size="16"/>立即采集并生成</button><button class="btn outline small" :disabled="busy" @click="action('publish-daily',{manual:true})"><Icon name="Send" :size="16"/>手动补发今日批次</button></div><p class="form-hint">手动任务通过服务端调用 GitHub workflow_dispatch。需要配置服务端 GitHub 凭证。</p></section><section class="form-card"><h3><Icon name="Clock3" :size="18"/>自动化计划</h3><p>下一次：{{dateLabel(nextPublication(app.settings.timezone).toISOString(),app.settings.timezone)}}<br>{{app.settings.timezone}} · 最多 {{app.settings.daily_target}} 条<br>自动发布：{{app.settings.auto_publish?'开启':'关闭'}}</p><RouterLink to="/account" class="source-link">调整发布计划<Icon name="ArrowUpRight" :size="16"/></RouterLink></section></div><h3 class="section-title">任务与失败记录</h3><div v-if="!app.jobs.length" class="table-empty">{{app.demo?'演示模式未执行真实 Agent，连接后显示真实任务日志。':'尚无运行记录。'}}</div><div v-for="job in app.jobs" :key="job.id" class="job-row"><Icon name="Terminal" :size="18"/><span><strong>{{job.kind}} · {{job.status}}</strong><small>{{dateLabel(job.created_at)}} · {{job.id}}</small><p v-if="job.error" class="form-error">{{job.error}}</p><small v-if="job.result">{{JSON.stringify(job.result)}}</small></span><button v-if="job.status==='failed'" class="btn outline small" :disabled="busy" @click="action('retry-job',{job_id:job.id})">重试</button></div><h3 class="section-title">候选新闻</h3><div v-if="!raws.length" class="table-empty">尚无候选。没有有效新闻源时，Agent 不会生成新闻。</div><div v-for="raw in raws" :key="raw.id" class="source-row"><Icon name="FileText"/><span><strong>{{raw.title}}</strong><small>{{raw.source_name}} · {{raw.source_published_at}}</small></span><a :href="secureUrl(raw.url)?raw.url:undefined" target="_blank" rel="noopener noreferrer" class="icon-btn" aria-label="候选原文"><Icon name="ExternalLink" :size="16"/></a></div><h3 class="section-title">运行时间与模型用量</h3><div v-for="run in runs" :key="run.id" class="job-row"><Icon name="Activity"/><span><strong>{{run.status}} · {{run.model||'未调用模型'}}</strong><small>{{run.duration_ms||0}} ms · 输入 {{run.input_tokens||0}} / 输出 {{run.output_tokens||0}} tokens</small><p v-if="run.error" class="form-error">{{run.error}}</p></span></div></template><template v-else-if="tab==='信息源'"><section class="form-card"><h3>添加合规 RSS 信息源</h3><form @submit.prevent="addSource" class="source-form"><label>来源名称<input v-model="sourceForm.name" required maxlength="120" placeholder="例如：官方研究博客"/></label><label>RSS / Atom URL<input v-model="sourceForm.url" type="url" required placeholder="https://…/feed.xml"/></label><label>分类<select v-model="sourceForm.category"><option v-for="c in categories" :key="c">{{c}}</option></select></label><label>使用权限与条款<input v-model="sourceForm.license_note" required maxlength="1000" placeholder="允许读取摘要的条款链接或授权记录"/></label><label>接入方式<select v-model="sourceForm.source_type"><option value="rss">RSS / Atom</option><option value="api">平台 API</option></select></label><label v-if="sourceForm.source_type==='api'">API 适配器<select v-model="sourceForm.api_adapter"><option value="newsapi">NewsAPI</option><option value="github">GitHub 热门项目</option><option value="huggingface">Hugging Face 热门模型</option></select></label><label>内容重点<select v-model="sourceForm.focus"><option value="general">综合动态</option><option value="model_update">大模型能力 / 版本升级</option></select></label><label class="checkbox-label"><input v-model="sourceForm.official" type="checkbox"/>这是已确认的官方第一手来源</label><label>允许的原文域名<input v-model="sourceForm.content_hosts" placeholder="example.com, www.example.com"/></label><label>配图策略<select v-model="sourceForm.image_policy"><option value="illustration">原创示意图</option><option value="licensed">已确认授权的实时图片</option></select></label><template v-if="sourceForm.image_policy==='licensed'"><label>图片许可与署名<input v-model="sourceForm.image_license" required placeholder="授权条款链接 + 作者署名规则"/></label><label>允许的图片域名<input v-model="sourceForm.image_hosts" required placeholder="images.example.com"/></label></template><button class="btn primary small" :disabled="busy"><Icon name="Plus" :size="16"/>添加来源</button></form></section><div v-if="!app.sources.length" class="table-empty">尚无已配置的信息源。只接入已确认允许自动读取的 RSS。</div><div v-for="s in app.sources" :key="s.id" class="source-row"><Icon name="Rss"/><span><strong>{{s.name}} <small>{{s.category}}</small></strong><small>{{s.url}}</small><small>最近采集：{{s.last_fetched_at?dateLabel(s.last_fetched_at):'尚未采集'}} · {{s.license_note}}</small></span><button class="btn outline small" :disabled="busy" @click="action('test-source',{id:s.id})">验证连接</button><button class="btn outline small" :disabled="busy" @click="toggleSource(s)">{{s.enabled?'禁用':'启用'}}</button></div></template><template v-else><section class="form-card"><h3><Icon name="KeyRound" :size="18"/>受信任 Agent 投稿凭证</h3><p>凭证仅允许提交草稿和查询自身任务。无法读取私人正文、发布内容或修改设置。原文仅在创建时显示一次。</p><form class="inline-form" @submit.prevent="createToken"><input v-model="clientName" required maxlength="80" placeholder="提交方名称，例如 research-agent" aria-label="投稿方名称"/><select v-model="purpose" aria-label="凭证权限"><option value="ingest">仅投稿（GPT / 外部 Agent）</option><option value="automation">自动化（GitHub 专用，含发布）</option></select><button class="btn primary small" :disabled="busy">生成投稿凭证<Icon name="Plus" :size="16"/></button></form><div v-if="newToken" class="one-time-token"><small>仅显示这一次。请保存到安全的 Secrets，关闭后无法找回。</small><code>{{newToken}}</code><button class="btn outline small" @click="copyToken"><Icon name="Copy" :size="15"/>复制</button><button class="btn text-btn small" @click="newToken=''">我已保存，隐藏凭证</button></div><div v-for="c in clients" :key="c.id" class="source-row"><Icon name="KeyRound" :size="17"/><span><strong>{{c.name}} · {{c.active?'有效':'已撤销'}}</strong><small>{{c.id}} · {{c.scopes.join(', ')}}</small></span><button v-if="c.active" class="btn outline small" :disabled="busy" @click="action('revoke-client',{id:c.id});refresh()">撤销</button></div></section><h3 class="section-title">最近投稿记录</h3><div v-if="!app.logs.length" class="table-empty">尚无投稿记录。测试步骤见 GPT_INTEGRATION.md。</div><div v-for="log in app.logs" :key="String(log.id)" class="job-row"><Icon name="Terminal" :size="17"/><span><strong>{{log.status}} · {{log.post_count}} 条</strong><small>{{log.created_at}} · {{log.error_code||'OK'}}</small></span></div><section class="form-card api-reference"><h3>统一投稿接口</h3><code>POST /functions/v1/news-ingest</code><code>POST /functions/v1/news-publish-daily</code><code>GET /functions/v1/news-job-status</code><p>投稿接口接受严格结构，服务端执行防重放、限流与幂等检查。批量任务返回 job_id；核验状态不会采信调用方声明。</p></section></template><div v-if="selected" class="modal-backdrop" @click.self="selected=''"><div role="dialog" aria-modal="true" class="confirm-dialog"><Icon name="Trash2" :size="28"/><h2>删除这条内容？</h2><p>{{confirmation}}</p><p>内容及其关联笔记和收藏将被移除。此操作无法撤销。</p><div><button class="btn outline" @click="selected=''">保留</button><button class="btn danger" :disabled="busy" @click="deleteSelected">确认删除</button></div></div></div></div></template>
